    val faithWorksPlan: List<ReadingPlanDay> by lazy {
        listOf(
            d(1, "Día 1: Justificados solo por Gracia mediante la Fe", "Efesios 2:1-9; Gálatas 2:15-21", 49, 2, listOf(p(49, "Efesios", 2), p(48, "Gálatas", 2)),
